import {SPECIES_PACKAGES} from './species-packages.js?v=20261102-selection1';
import {NAME_LANGUAGES,languageLabel} from './name-languages.js?v=20261101-scientific1';

export const INFO_REVIEWED='2026-11-02';
export const SOURCE_TITLES_EN=Object.freeze({
 'https://support.ebird.org/en/support/solutions/articles/48000804865':'eBird: multilingual bird names and four-letter codes (30 October 2025)',
 'https://www.birds.cornell.edu/clementschecklist/download/':'Cornell: eBird/Clements v2025 taxonomy downloads',
 'https://www.dda-web.de/downloads/publications/statusreports/vid_bestandssituation_2025.pdf':'DDA: Birds in Germany — Population Status 2025 (breeding birds pp. 36–44; waterbirds pp. 66–68)',
 'https://www.do-g.de/fileadmin/Ablage/DOG/Fachkommissionen/Kommission_Artenliste/Dokumente/Barthel_Kr%C3%BCger_2019_Liste_der_V%C3%B6gel_Deutschlands_3.2.pdf':'DO-G: German bird checklist, version 3.2 (2019); regular winter visitors and passage migrants'
});
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
const download=(url,label)=>`<a href="${esc(url)}" download>${esc(label)}</a>`;
export function informationFacts({birds,photos,regions}){
 const images=Object.values(photos).flatMap(p=>[p,...p.additional||[]]);
 const comparison=kind=>Object.values(photos).filter(p=>new Set([p,...p.additional||[]].filter(x=>(x.mediaType||'photo')===kind).flatMap(x=>x.sexes||[])).size===2).length;
 const lists=regions?.regions.flatMap(r=>[r.all,r.recent].filter(Boolean))||[];
 const stamps=lists.map(x=>x.updatedAt).sort((a,b)=>Date.parse(a)-Date.parse(b));
 return {species:birds.length,levels:[1,2,3].map(level=>birds.filter(s=>s.level===level).length),photoCount:images.filter(p=>(p.mediaType||'photo')==='photo').length,illustrationCount:images.filter(p=>p.mediaType==='illustration').length,photoComparisons:comparison('photo'),illustrationComparisons:comparison('illustration'),regionCount:regions?.regions.length||0,listCount:lists.length,oldest:stamps[0],newest:stamps.at(-1)};
}
export function renderInformation({english,birds,meta,germanNamesMeta={},photos={},regions=null}){
 const locale=english?'en-GB':'de-DE',f=informationFacts({birds,photos,regions});
 const choose=(de,en)=>english?en:de;
 const date=value=>new Date(value).toLocaleDateString(locale,{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
 const stamp=value=>new Date(value).toLocaleString(locale,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC';
 const built=/^\d{2}\.\d{2}\.\d{4}$/.test(meta.built)?date(meta.built.split('.').reverse().join('-')):esc(meta.built);
 const languages=NAME_LANGUAGES.map(l=>esc(languageLabel(l.code,english?'en':'de'))).join(', ');
 const levels=SPECIES_PACKAGES.map(p=>choose(p.de,p.en)).map((label,i)=>`${label}: ${f.levels[i]}`).join(' · ');
 const countryCoverage=regions?.countries.map(c=>{
  const count=regions.regions.filter(r=>r.parentCode===c.code).length,local=regions.regions.filter(r=>r.country===c.code&&r.code.split('-').length===3).length;
  const type=choose(c.code==='DE'?(count===1?'Bundesland':'Bundesländer'):c.code==='NL'?(count===1?'Provinz':'Provinzen'):c.code==='GB'?(count===1?'Landesteil':'Landesteile'):(count===1?'Region':'Regionen'),c.code==='DE'?(count===1?'federal state':'federal states'):c.code==='NL'?(count===1?'province':'provinces'):c.code==='GB'?(count===1?'constituent country':'constituent countries'):(count===1?'region':'regions'));
  return `${esc(english?c.nameEn:c.nameDe)}: ${count} ${type}${local?choose(` und ${local} lokale eBird-${local===1?'Region':'Regionen'}`,` and ${local} local eBird ${local===1?'region':'regions'}`):''}`;
 }).join('; ');
 const freshness=f.listCount?choose(`${f.regionCount} Gebiete einschließlich Länderlisten; ${f.listCount} verfügbare Artenlisten. Letzte erfolgreiche Listenaktualisierungen: `,`${f.regionCount} areas including country-wide lists; ${f.listCount} available species lists. Last successful list updates: `)+(f.oldest===f.newest?stamp(f.newest):`${stamp(f.oldest)} – ${stamp(f.newest)}`):choose('Regionale Daten sind in dieser Ansicht derzeit nicht verfügbar. Ohne Regionsfilter kann weiterhin gelernt werden.','Regional data is currently unavailable in this view. You can still learn without a regional filter.');
 const sources=meta.sources.map(s=>`<li>${link(s.url,english?SOURCE_TITLES_EN[s.url]||s.title:s.title)}</li>`).join('');
 const originalSources=english?`<details><summary>Original source titles</summary><ul data-name-content>${meta.sources.map(s=>`<li>${link(s.url,s.title)}</li>`).join('')}</ul></details>`:'';
 const blocks=[
 ['scope',choose('Artenbestand und Datenstand','Species coverage and data version'),
  choose(`<p>${esc(meta.selection)}</p>`,`<p>The learning data is an editorial selection focused on Germany: regular native breeding birds, established introduced breeding birds, documented waterbird visitors, regular landbird winter visitors and coastal passage migrants. Very local regular breeding birds are included. Rare vagrants are not a separate learning focus. Some DDA species are combined under a single eBird taxon.</p>`)+
  `<p>${levels}. ${choose('Artenpakete und Vorkommensstatus sind redaktionelle Einordnungen, keine Häufigkeitsrangliste oder Gefährdungsbewertung. Brutstatus beziehen sich auf Deutschland; „Rastvogel“ bezeichnet die Nutzung Deutschlands außerhalb der Brutzeit und bedeutet nicht automatisch „Wintergast“.','Species packages and occurrence statuses are editorial categories, not abundance rankings or conservation assessments. Breeding statuses refer to Germany; a non-breeding visitor is not automatically a winter visitor.')}</p>`+
  `<p>${choose('Ursprüngliche Datenaufbereitung','Original dataset prepared')}: ${built}. ${choose('Namensmatrix vom 30. Oktober 2025, geprüft gegen die offizielle eBird-Taxonomie v2025-4 (April 2026). Der Bestand wird nicht automatisch auf eine neue Taxonomie umgestellt. Sonderfälle und Zusammenfassungen sind bei der jeweiligen Art erläutert.','Names use the workbook dated 30 October 2025, checked against the official eBird taxonomy v2025-4 (April 2026). The dataset is not automatically migrated to a newer taxonomy. Exceptions and taxonomic combinations are explained in the species details.')}</p>`],
 ['names',choose('Sprachen, Namen und Codes','Languages, names and codes'),
  `<p>${choose('Verfügbare Namensarten','Available name types')}: ${languages}. ${choose('Oberflächensprache sowie Namen für Frage und Antwort werden unabhängig gewählt. Auch die binomialen wissenschaftlichen Namen lassen sich in beiden Richtungen üben. Im Nachschlagen erscheinen alle hinterlegten Namen. Fehlende Namensdaten werden nicht durch eine andere Sprache ersetzt.','The interface language and names for questions and answers are selected independently. Binomial scientific names can be practised in either direction. Lookup cards show every registered name. Missing names never fall back to another language.')}</p>`+
  `<p>${choose('Deutsche, englische, wissenschaftliche und niederländische Namen sowie Arten-IDs und Quick Find Codes stammen aus der offiziellen eBird-Taxonomie beziehungsweise ihrer mehrsprachigen Namensmatrix. Der englische US-Hauptname und abweichende britische Namen werden angezeigt und als englische Antwort akzeptiert. Niederländische Namen wurden aus derselben Namensmatrix übernommen; sie ändern weder den Artenbestand noch die Taxonomie.','German, English, scientific and Dutch names, species IDs and Quick Find Codes come from the official eBird taxonomy and its multilingual name matrix. The US English main name and any different British name are shown and accepted as English answers. Dutch names use the same matrix; adding them changes neither the species selection nor the taxonomy.')}</p>`+
  `<p>${choose(`Für ${germanNamesMeta.speciesCount||0} Arten sind zusätzlich belegte deutsche Namensvarianten hinterlegt. Aktuelle eindeutige Alternativnamen werden als deutsche Antwort akzeptiert; historische und mehrdeutige Namen bleiben Zusatzinformationen. Auch diese Varianten werden bei der Suche gefunden. Namen und originale Quellen- und Bildtitel bleiben in ihrer jeweiligen Sprache; erklärende Begleittexte werden im englischen UI übersetzt.`,`Documented German name variants are provided for ${germanNamesMeta.speciesCount||0} species. Current unambiguous alternatives are accepted as German answers; historical and ambiguous names are shown for reference. These variants are also searchable. Names and original source/image titles retain their language; explanatory notes are translated in the English interface.`)}</p>`+
  `<p>${choose('Quick Find Codes sind offizielle vierstellige Eingabekürzel, keine eindeutigen Arten-IDs. Mehrere Arten können denselben Code tragen; die Suche zeigt alle Treffer. Hinterlegte weitere Codes werden akzeptiert. Wo die offizielle Tabelle keinen separaten common-name Quick Code führt, wird ihr Banding Code verwendet und im Artdetail gekennzeichnet. Wissenschaftliche Quick Codes werden nicht verwendet.','Quick Find Codes are official four-letter entry shortcuts, not unique species IDs. Several species can share a code; search shows all matches. Recorded alternative codes are accepted. Where the official table has no separate common-name Quick Code, its banding code is used and identified in the species details. Scientific-name Quick Codes are not used.')}</p>`+
  `<p>${download('languages/nl.json',choose('Niederländische Namen und Herkunft (JSON)','Dutch names and provenance (JSON)'))} · ${download('german-names.json',choose('Deutsche Namensvarianten und Quellen (JSON)','German name variants and sources (JSON)'))}</p>`],
 ['regions',choose('Regionale Artenauswahl mit eBird','Regional species selection with eBird'),
  `<p>${countryCoverage||choose('Die unterstützten Länder und Regionen erscheinen in den Lerneinstellungen, sobald die regionalen Daten geladen sind','Supported countries and regions appear in the study settings when regional data is available')}. ${choose('Die Gebietsstruktur und Namen folgen eBird. Land, Region beziehungsweise Landesteil und gegebenenfalls lokale Region werden nacheinander gewählt.','Area names and hierarchy follow eBird. Choose a country, then a region or constituent country, and a local region where available.')}</p>`+
  `<p>${choose(`„In den letzten 30 Tagen beobachtet“ verwendet die jüngsten eBird-Meldungen dieses Zeitfensters; „Alle dort nachgewiesenen Taxa“ verwendet die Gesamt-Nachweisliste. Beide filtern nur die vorhandenen ${f.species} Lernarten. Mehr eBird-Taxa bedeuten nicht automatisch mehr verfügbare Lernarten. Aktuelle Meldungen sind keine Häufigkeitsrangliste oder Sichtungsgarantie; Gesamtlisten können historische Seltenheiten enthalten. Regionsfilter ändern nicht die auf Deutschland bezogenen Statusangaben der Arten.`,`“Observed in the last 30 days” uses recent eBird reports in that time window; “All recorded taxa” uses the all-time list. Both only filter the existing ${f.species} learning species. Additional eBird taxa do not automatically add learning species. Recent reports are not abundance rankings or a promise of sightings; all-time lists can include historical rarities. Regional filters do not change the species statuses, which refer to Germany.`)}</p>`+
  `<p>${choose('Ein täglicher Abruf ist über GitHub Actions eingeplant; Aktualisierungen können verspätet eintreffen oder ausfallen. Bei Fehlern bleibt pro Liste nach Möglichkeit der letzte gültige Stand erhalten. Fehlt die gewählte Liste oder ist sie leer, wird nicht stillschweigend auf alle Arten erweitert. Ein über drei Tage alter Stand wird bei der Auswahl gekennzeichnet.','A daily refresh is scheduled through GitHub Actions; updates may be delayed or fail. Where possible, each failed list retains its last valid snapshot. Missing or empty selected lists never silently expand to all species. Lists older than three days are flagged in the selection.')}</p>`+
  `<p>${choose('Die experimentellen saisonalen Häufigkeitsstufen nutzen einmalig heruntergeladene eBird-Histogrammdaten 2021–2025 für alle 16 Bundesländer und Garmisch-Partenkirchen. In 15 Bundesländern reichen die Stichproben in allen Jahreszeiten aus; im Saarland in keiner, in Garmisch-Partenkirchen nur im Frühjahr und Sommer. Fehlende oder unzureichende Saisondaten werden durch die regionale Artenliste ersetzt und ausdrücklich gekennzeichnet. Häufig bedeutet mindestens 10 %, mittel 1 bis unter 10 %, selten über 0 bis unter 1 % der vollständigen Listen. Häufig und mittel sind standardmäßig aktiv. Nullwerte oder fehlende Nachweise werden nicht als selten eingestuft; Meldehäufigkeit ist keine Bestandsgröße. Aktuelle Besonderheiten werden automatisch ergänzt und sind gültige bemerkenswerte eBird-Nachweise, höchstens 14 Tage ab Beobachtung; Snapshots über drei Tage werden nicht verwendet. Globale Artenpakete schränken regionale Lernrunden nicht ein. Laufende Runden behalten die Auswahl vom Start.','Experimental seasonal frequency groups use one-off eBird histogram downloads for 2021–2025 for all 16 German states and Garmisch-Partenkirchen. Samples support all seasons in 15 states, none in the Saarland, and spring and summer in Garmisch-Partenkirchen. Missing or insufficient seasonal data fall back to the regional list, explicitly labelled. Frequent means at least 10%, medium 1% to less than 10%, rare above 0% but less than 1% of complete checklists. Frequent and medium are selected by default. Zero/missing reports are not rare; reporting frequency is not population abundance. Current additions are automatic and use valid notable eBird reports, for at most 14 days after observation; snapshots older than three days are not used. Global species packages do not restrict regional rounds. Active rounds retain their original selection.')} <a href="seasonal-data.html">${choose('Methode, Quellen und Nutzungsbedingungen','Method, sources and terms')}</a></p>`+
  `<p class="notice">${esc(freshness)}</p><p>${download('regions.json',choose('Regionale Artenlisten und Zeitstempel (JSON)','Regional species lists and timestamps (JSON)'))}</p>`],
 ['pictures',choose('Bilder und Nachweise','Pictures and credits'),
  `<p>${choose(`Die App liefert ${f.photoCount} Fotos und ${f.illustrationCount} historische wissenschaftliche Illustrationen aus Wikimedia Commons mit. Beschriftete Fotos zeigen bei ${f.photoComparisons} Arten beide Geschlechter; bei ${f.illustrationComparisons} Arten ergänzen gekennzeichnete Illustrationen den Vergleich. Zuordnung und Figuren sind durch Quellenbeschreibung oder Originallegende belegt. Bilder sind nicht maßstabsgetreu; Gefieder kann von Alter, Jahreszeit und Unterart abhängen. Historische Illustrationen sind idealisierte Darstellungen.`,`The app includes ${f.photoCount} photographs and ${f.illustrationCount} historical scientific illustrations from Wikimedia Commons. Labelled photographs show both sexes for ${f.photoComparisons} species; labelled illustrations supplement the comparison for ${f.illustrationComparisons} species. Assignments and figures are supported by the source description or original caption. Images are not to scale; plumage may vary with age, season and subspecies. Historical illustrations are idealised depictions.`)}</p>`+
  `<p>${choose('Jedes Bild hat Urheberangabe, Original-Link, Lizenz und vollständigen Bildnachweis. Die jeweilige Lizenz gilt für das zugehörige Bild. Im Nachschlagen erscheinen Bilder nach Aktivierung von „Artenbilder“. Beim Lernen erscheinen sie in der Vorstellung neuer Ziele und nach der Bewertung, bei Karteikarten nach der Selbsteinschätzung. Für Ladefehler gibt es einen Link zur artbezogenen eBird-Galerie.','Each image has attribution, an original source link, a licence and a complete credit. Each licence applies to its corresponding image. Lookup pictures appear when “Species pictures” is enabled. Study pictures appear when introducing new targets and after grading, including self-assessment for flashcards. If an image cannot load, a species-specific eBird gallery link is available.')}</p>`+
  `<p>${download('photos.json',choose('Vollständige Bildnachweise (JSON)','Complete image credits (JSON)'))} · ${link('https://commons.wikimedia.org/wiki/Commons:Reusing_content_outside_Wikimedia',choose('Wikimedia: Bildnutzung und Lizenzen','Wikimedia: reuse and licences'))}</p>`],
 ['privacy',choose('Speicherung und Netzwerkzugriffe','Storage and network requests'),
  `<p>${choose('Die App setzt keine Cookies, auch keine Drittanbieter-Cookies. Stattdessen nutzt sie den lokalen Browserspeicher, damit dein Lernstand und deine Einstellungen beim nächsten Besuch erhalten bleiben. Dafür werden weder Name noch E-Mail-Adresse oder ein Benutzerkonto benötigt.','The app does not set cookies, including third-party cookies. Instead, it uses local browser storage to keep your progress and preferences for your next visit. This does not require your name, email address or a user account.')}</p>`+
  `<p>${choose('Lernstände und gespeicherte Einheiten liegen in IndexedDB in diesem Browser. Suche, Filter, Sprachwahl, Lerneinstellungen und Farbschema werden lokal gespeichert und von beiden UI-Sprachen gemeinsam verwendet. Ein kurzlebiger tabbezogener Eintrag hält beim UI-Sprachwechsel die aktive Ansicht aufrecht. Im Lernmodus werden Bilder der aktuellen und der nächsten beiden Fragen vorbereitet und in einem lokalen Bildcache gespeichert. Cache und ältere bei der Umstellung aufbewahrte Einstellungs- und Einheitskopien können bis zum Löschen der Websitedaten im Browser verbleiben.','Learning progress and saved sessions are kept in IndexedDB in this browser. Search, filters, languages, study preferences and appearance are stored locally and shared by both interface languages. A short-lived tab entry preserves the active view during an interface-language change. Study pictures for the current and next two questions are prepared and stored in a local image cache. The cache and older preference/session copies retained during migration may remain until the browser’s site data is cleared.')}</p>`+
  `<p>${choose('Gespeichert werden Antwortzahlen, Fehler, Lernrichtung, Antwortmethode, zeitversetzte Bestätigungen und Wiederholungstermine. Das Tagesbudget speichert das lokale Datum und bereits vorgestellte Lernziele. Frühere Lernwerte bleiben als historische Daten erhalten. Pausierte Einheiten enthalten außerdem Reihenfolge, Vorstellungsphase, sichtbare Antwortmöglichkeiten, Antwortentwurf und zuletzt bewertete Antwort.','Stored data includes answer and error counts, learning direction, answer method, spaced confirmations and review dates. The daily budget stores the local date and targets already introduced. Earlier progress is preserved as historical data. Paused sessions also contain order, introduction phase, visible answer choices, draft answers and the last graded answer.')} <a href="#lernmethode">${choose('So funktioniert das Lernen','How learning works')}</a></p>`+
  `<p>${choose('Die veröffentlichte App wird über GitHub Pages geladen. App-Dateien, Bilder und regionale JSON-Listen kommen vom selben Hosting-Ursprung. GitHub verarbeitet dabei Verbindungsdaten und protokolliert laut seiner Pages-Dokumentation die IP-Adresse zu Sicherheitszwecken. Die App sendet weder Quizantworten noch Lernstände an eine zentrale Lerndatenbank. Es gibt keine Anmeldung, eingebundenen Analytics, Tracking-Dienste, externen Schriftarten oder automatische Standortabfrage. Externe Quellen-, Lizenz- und Galerieseiten werden erst beim Anklicken aufgerufen.','The published app is loaded from GitHub Pages. App files, images and regional JSON lists are served from the same hosting origin; GitHub processes connection data and, according to its Pages documentation, logs visitor IP addresses for security purposes. The app does not send quiz answers or progress to a central learning database. It has no sign-in, embedded analytics, tracking services, external fonts or automatic location lookup. External source, licence and gallery pages are only requested when you follow their links.')}</p>`+
  `<p>${link('https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection',choose('GitHub Pages: Datenerfassung','GitHub Pages: data collection'))} · ${link('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement',choose('GitHub: Datenschutzerklärung','GitHub: privacy statement'))}</p>`+
  `<p>${choose('Die eBird-API wird vom Aktualisierungsablauf in GitHub Actions aufgerufen, nicht vom Browser beim Auswählen einer Region. Der API-Schlüssel liegt als GitHub Actions Secret vor und wird nicht mit der Web-App ausgeliefert. Veröffentlicht werden Arten-IDs, Regionsbezeichnungen, Anzahlen und Zeitstempel; keine einzelnen Beobachtungen, Beobachternamen oder genauen Fundorte.','The eBird API is called by the refresh workflow in GitHub Actions, not by your browser when selecting a region. The API key is held as a GitHub Actions secret and is not delivered with the web app. Published snapshots contain species IDs, region labels, counts and timestamps, not individual observations, observer names or precise observation locations.')}</p>`],
 ['backup',choose('Sicherung, Import und Domainwechsel','Backups, import and changing domains'),
  `<p>${choose('Der JSON-Export in der Statistik enthält die Lernwerte aller unterstützten Antwortsprachen und der Codes einschließlich Lernrichtungen, Methodennachweisen und Tagesbudget sowie Versions-, Taxonomie- und Exportmetadaten. Suche, Einstellungen, pausierte Einheiten, Antwortentwürfe und Bildcache werden nicht exportiert. Nach der Dateiauswahl zeigt die App zuerst eine Vorschau mit Dateiname, Sicherungsdatum und Umfang. Erst der Ersetzen-Button überschreibt alle bisherigen Lernwerte über sämtliche Antwortsprachen hinweg und beendet pausierte Einheiten. Die Daten werden nicht zusammengeführt. Die Datei bleibt im Browser; sie wird nicht hochgeladen. Sichere den bisherigen Stand vor einem Import oder Zurücksetzen. Wenn das Speichern fehlschlägt, bleiben der bisherige Lernstand und die pausierten Einheiten erhalten.','The JSON export in Statistics contains progress for all supported answer languages and codes, including learning directions, method evidence and daily budget, plus version, taxonomy and export metadata. Search, preferences, paused sessions, draft answers and the image cache are not exported. Selecting a file first shows a preview with its name, backup date and scope. Only the Replace button overwrites all existing progress across all answer languages and ends paused sessions. Records are not merged. The file stays in your browser and is not uploaded. Back up your existing progress before importing or resetting. If saving fails, your previous progress and paused sessions are retained.')}</p>`+
  `<p>${choose('Browserspeicher ist an den Website-Ursprung gebunden. Beim Wechsel etwa von chatgpt.site zu github.io exportierst du die Lernwerte auf der bisherigen Seite und importierst sie auf der neuen Seite. Die neue Seite kann den Speicher der alten Domain nicht automatisch lesen. Einstellungen werden auf der neuen Seite erneut gewählt.','Browser storage is tied to the website origin. When moving, for example, from chatgpt.site to github.io, export progress on the old site and import it on the new site. The new site cannot automatically read the old domain’s storage. Choose your preferences again on the new site.')}</p>`+
  `<p>${choose('Privatmodus, Browserbereinigung oder gelöschte Websitedaten können Lernstände entfernen. „Fortschritt zurücksetzen“ leert den aktiven Lernstand und die aktuellen gespeicherten Einheiten; Einstellungen, Bildcache und alte Übernahmekopien werden dadurch nicht vollständig entfernt. Um alle lokalen Kopien zu entfernen, lösche die Websitedaten im Browser. Es gibt keinen geräteübergreifenden Abgleich; Offline-Nutzung ist nicht zugesichert.','Private browsing, browser cleanup or deleting site data can remove progress. “Reset progress” clears active progress and current saved sessions; it does not fully remove preferences, image caches or old migration copies. To remove all local copies, clear the browser’s site data. There is no cross-device sync; offline use is not guaranteed.')}</p>`],
 ['sources',choose('Quellen und Unabhängigkeit','Sources and independence'),
  `<ul>${sources}</ul>${english?'<p>English link labels describe the sources; linked documents may be in German. Their original titles are available below.</p>':''}${originalSources}<p>${download('species.json',choose('Artenstammdaten (JSON)','Species data (JSON)'))} · ${link('validation.json',choose('Validierungsbericht','Validation report'))}</p><p>${choose('BirdNames DE ist ein unabhängiges Lernangebot und kein Produkt des Cornell Lab oder des DDA. Der Lernbestand ist keine vollständige nationale Nachweisliste.','BirdNames DE is an independent learning app, not a Cornell Lab or DDA product. The learning dataset is not a complete national checklist.')}</p>`],
 ['project',choose('Projekt und Lizenz','Project and licence'),
  `<p>${choose('Der originale Programmcode der App, die Skripte und die Projektkonfiguration stehen unter der MIT-Lizenz (© 2026 DG1TAL). Diese Lizenz gilt nicht für die Arten- und Taxonomiedaten, Namen, Quick Find Codes, regionalen Daten, Fotos oder Illustrationen. Für jedes Bild gelten die bei ihm angegebenen Lizenz- und Urheberhinweise.','The original app code, scripts and project configuration are licensed under the MIT License (© 2026 DG1TAL). This licence does not cover species and taxonomy data, names, Quick Find Codes, regional data, photographs or illustrations. Each image has its own licence and attribution shown alongside it.')}</p>`+
  `<p>${link('https://github.com/dg1tal/birdnamesde',choose('Quellcode auf GitHub','Source code on GitHub'))} · ${link('https://github.com/dg1tal/birdnamesde/blob/main/LICENSE',choose('MIT-Lizenztext','MIT License text'))}</p>`]
 ];
 return `<h1>${choose('Daten & Datenschutz','Data & privacy')}</h1><div class="panel information-page"><p class="data-count"><strong>${f.species} ${choose('Arten','species')}</strong> · eBird/Clements ${esc(meta.taxonomy)}</p><p class="muted">${choose('Angaben geprüft am','Information reviewed on')} ${date(INFO_REVIEWED)}.</p>${blocks.map(([id,title,body])=>`<section aria-labelledby="info-${id}"><h2 id="info-${id}">${title}</h2>${body}</section>`).join('')}</div>`;
}
